#include <bits/stdc++.h>
using namespace std;
int main(){
    int n1,n2,tc=0;
    while (cin >> n1 >> n2 && (n1||n2)) {
        tc++;
        vector<int> a(n1), b(n2);
        for (auto &x : a) cin >> x;
        for (auto &x : b) cin >> x;
        vector<vector<int>> dp(n1+1, vector<int>(n2+1,0));
        for (int i=1;i<=n1;i++)
            for (int j=1;j<=n2;j++)
                dp[i][j] = a[i-1]==b[j-1] ? dp[i-1][j-1]+1 : max(dp[i-1][j], dp[i][j-1]);
        if (tc>1) cout << "\n";
        cout << "Twin Towers #" << tc << "\n";
        cout << "Number of Tiles : " << dp[n1][n2] << "\n";
    }
}

